#!/usr/bin/env bash
# Build the real-producer corpus: core modules written by the pinned Rust toolchain (rustc
# 1.99.1, target wasm32-wasip2) with bindings generated by the pinned wit-bindgen CLI 0.62.0,
# exactly what `cargo build --target wasm32-wasip2` links, but with wasm-component-ld told to
# stop before componentizing (`-Clink-arg=--skip-wit-component`): the core module and its
# component-type custom sections (several for std crates: the crate's world, libstd's and
# wasi-libc's).
#
#   tools/wasm-jco/tests/corpus/build.sh OUT_DIR
#
# Writes OUT_DIR/NAME.core.wasm for every crate of CRATES below. Skips (exit 0, message) when the
# toolchain or wit-bindgen is absent. The sources are copied to a scratch directory first; the
# generated bindings never land in the repository. Crates come from crates.io at the versions
# and checksums of rust/Cargo.lock, into their own CARGO_HOME ($CORPUS_CARGO_HOME); building runs
# their build scripts (wit-bindgen's copies a static library, libc's probes cfgs); no proc macro
# is used (bindings come from the CLI).
set -euo pipefail
here=$(cd "$(dirname "$0")" && pwd)
. "$here/../pins.sh"
out=${1:?usage: build.sh OUT_DIR}

have_tool wit-bindgen "$WIT_BINDGEN" "$WIT_BINDGEN_SHA256" || exit 0
rustc_bin=$RUST_TOOLCHAIN/bin/rustc
if [[ ! -x $rustc_bin ]] || [[ $("$rustc_bin" --version) != "$RUSTC_ID" ]]; then
  echo "skip: Rust $RUST_VERSION not installed at $RUST_TOOLCHAIN"; exit 0
fi
[[ -d $RUST_TOOLCHAIN/lib/rustlib/wasm32-wasip2 ]] || { echo "skip: no wasm32-wasip2 std in $RUST_TOOLCHAIN"; exit 0; }
have_tool wasm-component-ld "$RUST_TOOLCHAIN/lib/rustlib/x86_64-unknown-linux-gnu/bin/wasm-component-ld" "$WASM_COMPONENT_LD_SHA256" || exit 0

# NAME  WIT-DIR  WORLD  (the crate is NAME; kitchen-ns shares kitchen's bindings, no_std)
CRATES=(
  "kitchen kitchen kitchen"
  "kitchen-ns - -"
  "kdriver kitchen kdriver"
  "astream astream astream"
  "adriver astream adriver"
  "res res res"
  "rdriver res rdriver"
)

work=$(mktemp -d /tmp/wasm-jco-corpus-src-XXXXXX)
trap 'rm -rf "$work"' EXIT
cp -r "$here/rust" "$work/rust"
for c in "${CRATES[@]}"; do
  read -r name wdir world <<< "$c"
  [[ $wdir == - ]] && continue
  "$WIT_BINDGEN" rust "$work/rust/$wdir/wit" --world "$world" --out-dir "$work/rust/$name/src" --format > /dev/null 2>&1
done

export RUSTUP_HOME=$RUST_HOME/rustup CARGO_HOME=$CORPUS_CARGO_HOME
export PATH=$RUST_TOOLCHAIN/bin:$PATH
export CARGO_TARGET_DIR=${SIL_CORPUS_TARGET:-/tmp/wasm-jco-corpus-target}
export RUSTFLAGS="-Clink-arg=--skip-wit-component --remap-path-prefix=$work=/corpus"
mkdir -p "$out" "$CARGO_HOME"
cd "$work/rust"
for c in "${CRATES[@]}"; do
  read -r name _ _ <<< "$c"
  # one crate per invocation: features are not unified between std and no_std crates
  cargo build --locked --release --target wasm32-wasip2 -p "$name" 2>&1 | grep -E '^(error|warning: unused)' || true
  cp "$CARGO_TARGET_DIR/wasm32-wasip2/release/${name//-/_}.wasm" "$out/$name.core.wasm"
done
# an unoptimised build with DWARF (several MB): the large input of the suite
cargo build --locked --target wasm32-wasip2 -p kitchen 2>&1 | grep -E '^error' || true
cp "$CARGO_TARGET_DIR/wasm32-wasip2/debug/kitchen.wasm" "$out/kitchen-debug.core.wasm"
ls -la "$out"
